// Recover the address the customer actually wrote to.
//
// NEVER read Delivered-To. On this mail system it is written once, by the final
// delivery hop, and always contains the central intake mailbox -- so it looks
// like a valid Kayan address while being the same wrong answer every time.
// That failure presents as a mapping problem, not a header problem.
// Settings arrive on a node in the item stream, and an HTTP Request node
// REPLACES each item with its response body -- so $input here is N copies of
// the settings payload, not the mail. Read the mail from the trigger and the
// settings by name; that is why Get Inquiry Settings runs once.
const s = $('Get Inquiry Settings').first().json.message || {};
const FUNNEL = String(s.forwarding_mailbox || 'inquiries-inbox@kayan-eg.net').toLowerCase();
const INTERNAL = String(s.internal_domains || 'kayan-eg.net\nkayan-eg.com')
  .split('\n').map(x => x.trim().toLowerCase().replace(/^@/, '')).filter(Boolean);

const RE = /[\w.+-]+@[\w.-]+\.\w+/g;
function addrs(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.flatMap(addrs);
  if (typeof v === 'object') {
    if (v.value) return addrs(v.value);
    if (v.address) return [v.address];
    if (v.text) return addrs(v.text);
    return [];
  }
  return String(v).match(RE) || [];
}
const norm = a => String(a || '').trim().toLowerCase();
const isInternal = a => INTERNAL.includes((norm(a).split('@')[1] || ''));

const ORDER = ['Envelope-To', 'Received-For', 'Bcc', 'To Header', 'Cc Header', 'Manual Forward Sender'];
const out = [];

for (const item of $('IMAP Email Trigger').all()) {
  const j = item.json;
  const h = j.headers || {};
  const get = k => h[k] ?? h[k.toLowerCase()] ?? h[k.replace(/-/g, '')] ?? null;

  const envelopeTo  = addrs(get('envelope-to'));
  const receivedRaw = Array.isArray(get('received')) ? get('received').join('\n') : String(get('received') || '');
  const receivedFor = (receivedRaw.match(/for\s+<?[\w.+-]+@[\w.-]+\.\w+>?/gi) || [])
    .map(m => (m.match(RE) || [])[0]).filter(Boolean);

  const fromEmail = norm(addrs(j.from ?? get('from'))[0]);
  const keep = list => [...new Set(list.map(norm))].filter(a => a && a !== FUNNEL && isInternal(a));

  const cand = {
    'Envelope-To':  keep(envelopeTo),
    'Received-For': keep(receivedFor),
    'Bcc':          keep(addrs(j.bcc ?? get('bcc'))),
    'To Header':    keep(addrs(j.to  ?? get('to'))),
    'Cc Header':    keep(addrs(j.cc  ?? get('cc'))),
  };

  // A staff member forwarding customer mail by hand: the envelope points at the
  // funnel, so the forwarding employee is the owner.
  const envelopeHitsFunnel = addrs(get('envelope-to')).map(norm).includes(FUNNEL);
  if (isInternal(fromEmail) && fromEmail !== FUNNEL) cand['Manual Forward Sender'] = [fromEmail];

  const all = [];
  for (const k of ORDER) for (const a of (cand[k] || [])) if (!all.includes(a)) all.push(a);

  let method = 'Unresolved', recipient = null;
  for (const k of ORDER) if ((cand[k] || []).length) { method = k; recipient = cand[k][0]; break; }

  const messageClass = !isInternal(fromEmail) ? 'external'
    : (envelopeHitsFunnel || cand['Envelope-To'].length === 0) ? 'manual_forward' : 'internal';

  out.push({ json: { ...j,
    _recipient: recipient,
    _recipients: all,
    _resolution_method: method,
    _from_email: fromEmail,
    _message_class: messageClass,
  }, binary: item.binary });
}
return out;

// ~88% of what lands in the funnel is not a new customer inquiry. Filtering
// before the LLM call is what keeps cost and rate-limit exposure proportional
// to inquiry volume rather than to total company mail.
const s = $('Get Inquiry Settings').first().json.message || {};
const lines = v => String(v || '').split('\n').map(x => x.trim().toLowerCase()).filter(Boolean);

const FUNNEL    = String(s.forwarding_mailbox || 'inquiries-inbox@kayan-eg.net').toLowerCase();
const SUPPLIERS = lines(s.supplier_domains);
const NOISE     = lines(s.noise_sender_patterns);

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const from = j._from_email || '';
  const dom  = from.split('@')[1] || '';
  const h = j.headers || {};
  const g = k => String(h[k] ?? h[k.toLowerCase()] ?? '');

  let reason = null;
  if (!from)                                     reason = 'no sender address';
  else if (from === FUNNEL)                      reason = 'loop guard: sent from the funnel itself';
  // ERPNext mails its own notifications to staff, who forward them here. Without
  // this the new intake would classify its own output and notify again.
  else if (NOISE.some(p => from.includes(p)))    reason = 'noise sender pattern';
  else if (/auto-(generated|replied)/i.test(g('auto-submitted'))) reason = 'auto-submitted';
  else if (g('list-unsubscribe'))                reason = 'bulk or marketing';
  else if (SUPPLIERS.includes(dom))              reason = 'supplier or principal domain';
  else if (j._message_class === 'internal')      reason = 'internal correspondence';

  out.push({ json: { ...j, _noise: !!reason, _drop_reason: reason }, binary: item.binary });
}
return out;

// Manual forwards keep attachments intact but rewrite the envelope: From is the
// Kayan employee, and the customer sits in an Outlook-style quoted block. Note
// that block often carries only Cc, no To, because RFQs go out by BCC blast.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let email = null, name = null, subject = null, sent = null;

  if (j._message_class === 'manual_forward') {
    const body = j.textPlain || j.text ||
      String(j.textHtml || '').replace(/<[^>]+>/g, ' ');

    const m = body.match(/From:\s*"?([^"<\n]*?)"?\s*<?([\w.+-]+@[\w.-]+\.\w+)>?/i);
    if (m) { name = (m[1] || '').trim() || null; email = m[2].toLowerCase(); }

    const sub = body.match(/^\s*Subject:\s*(.+)$/mi);
    if (sub) subject = sub[1].trim();

    const dt = body.match(/^\s*Sent:\s*(.+)$/mi);
    if (dt) sent = dt[1].trim();
  }

  const external = j._message_class === 'external';
  out.push({ json: { ...j,
    _customer_email:   external ? j._from_email : email,
    _customer_name:    external ? (j.from && j.from.value && j.from.value[0] && j.from.value[0].name) || null : name,
    _original_subject: subject || j.subject || null,
    _original_sent:    sent || j.date || null,
  }, binary: item.binary });
}
return out;

let raw = '';
try { raw = $json.choices[0].message.content || ''; } catch (e) { raw = ''; }
const m = raw.match(/\{[\s\S]*\}/);
let p = {};
try { p = m ? JSON.parse(m[0]) : {}; } catch (e) { p = {}; }
const src = $('Unwrap Forwarded Message').first().json;
return [{ json: { ...src,
  is_inquiry: p.is_inquiry !== false,
  classification: p.classification || null,
  confidence: p.confidence ?? 0,
  priority: p.priority || 'Medium',
  summary: p.summary || null } }];

// The previous workflow sent every non-image attachment into a hard-coded PDF
// extractor. Spreadsheets are the most common attachment here (BoQs), so that
// path failed on the majority of real mail.
//
// Inline images are skipped. Almost every business email carries an embedded
// signature logo referenced by cid: in the body; OCR'ing those wastes an LLM
// call per message and returns nothing useful.
const body = String($json.text || $json.textPlain || '');
const out = [];

for (const item of $input.all()) {
  const bin = item.binary || {};
  const keys = Object.keys(bin);
  if (!keys.length) { out.push({ json: { ...item.json, _att_kind: 'none' } }); continue; }

  for (const key of keys) {
    const f = bin[key];
    const name = String(f.fileName || '').toLowerCase();
    const ext  = name.split('.').pop() || '';
    const size = Number(f.fileSize || 0);

    // Signature/inline artwork: referenced by cid, or an unnamed small image.
    const cid = String(f.cid || f.contentId || '').replace(/[<>]/g, '');
    const isInline = (f.contentDisposition === 'inline')
      || (cid && body.includes(cid))
      || (/^image\d*\.(png|jpg|jpeg|gif)$/i.test(name));

    let kind = 'unknown';
    if (['png','jpg','jpeg','gif','bmp','tif','tiff','webp'].includes(ext)) kind = 'image';
    else if (ext === 'pdf')                                    kind = 'pdf';
    else if (['xlsx','xlsm','xls','csv'].includes(ext))        kind = 'spreadsheet';
    else if (['docx','doc','rtf','txt'].includes(ext))         kind = 'document';
    else if (['zip','rar','7z'].includes(ext))                 kind = 'archive';

    if (kind === 'image' && isInline) {
      out.push({ json: { ...item.json, _att_key: key, _att_name: f.fileName,
                         _att_ext: ext, _att_kind: 'skipped',
                         _skip_reason: 'inline signature image' } });
      continue;
    }

    out.push({
      json: { ...item.json, _att_key: key, _att_name: f.fileName, _att_ext: ext,
              _att_kind: kind, _att_size: size },
      binary: { [key]: f },
    });
  }
}
return out;

// n8n cannot expand .rar natively, and RAR is not covered by PRD FR-7 (which
// lists ZIP). Real mail contains them, so flag rather than fail: the file is
// still attached to the ticket for a human to open.
return $input.all().map(i => ({ json: { ...i.json,
  _unsupported: true,
  _unsupported_reason: `Archive .${i.json._att_ext} cannot be expanded automatically`,
  _extracted_text: '' } }));

// Bills of Quantities run to hundreds of rows. Parsing them structurally rather
// than feeding the whole sheet to the LLM keeps extraction affordable and
// accurate; the model is reserved for unstructured bodies and scanned PDFs.
const HEADER_HINTS = {
  description: ['description','item description','item','material','specification','desc','بيان','الوصف'],
  quantity:    ['qty','quantity','q-ty','amount','no.','count','الكمية'],
  uom:         ['uom','unit','u/m','measure','الوحدة'],
  code:        ['code','item code','ref','reference','tag','item no','sn'],
};
const norm = v => String(v ?? '').trim().toLowerCase();
const match = (cell, hints) => hints.some(h => norm(cell) === h || norm(cell).includes(h));

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { _boq_items: [], _boq_rows: 0 } }];

// Find the header row: the first row where at least two hint groups match.
let headerIdx = -1, cols = {};
for (let i = 0; i < Math.min(rows.length, 25); i++) {
  const vals = Object.values(rows[i]);
  const found = {};
  vals.forEach((v, idx) => {
    for (const [field, hints] of Object.entries(HEADER_HINTS)) {
      if (!(field in found) && match(v, hints)) found[field] = Object.keys(rows[i])[idx];
    }
  });
  if (Object.keys(found).length >= 2) { headerIdx = i; cols = found; break; }
}

const items = [];
if (headerIdx >= 0) {
  for (const r of rows.slice(headerIdx + 1)) {
    const desc = cols.description ? String(r[cols.description] ?? '').trim() : '';
    const qty  = cols.quantity    ? parseFloat(String(r[cols.quantity] ?? '').replace(/[^0-9.\-]/g, '')) : null;
    if (!desc || desc.length < 3) continue;
    items.push({
      description: desc,
      quantity: Number.isFinite(qty) ? qty : null,
      uom: cols.uom ? String(r[cols.uom] ?? '').trim() || null : null,
      customer_item_code: cols.code ? String(r[cols.code] ?? '').trim() || null : null,
      source: 'spreadsheet',
    });
  }
}
return [{ json: { _boq_items: items, _boq_rows: rows.length, _boq_header_row: headerIdx } }];

const parts = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j._extracted_text) parts.push(j._extracted_text);
  else if (j.text) parts.push(j.text);
  else if (j.data) parts.push(String(j.data));
  else { try { parts.push(j.choices[0].message.content); } catch (e) {} }
}
return [{ json: { _attachment_text: parts.filter(Boolean).join('\n\n---\n\n').slice(0, 60000) } }];

let raw = '';
try { raw = $json.choices[0].message.content || ''; } catch (e) { raw = ''; }
const m = raw.match(/\{[\s\S]*\}/);
let p = {};
try { p = m ? JSON.parse(m[0]) : {}; } catch (e) { p = {}; }
return [{ json: p }];

// Assemble the single payload for ingest_inquiry_email. Everything the previous
// eight-call chain discovered incrementally is decided server-side now.
const src = $('Unwrap Forwarded Message').first().json;
const cls = $('Parse AI Output').first().json || {};
let ext = {};
try { ext = $('Parse Extraction Output').first().json || {}; } catch (e) { ext = {}; }
let boq = [];
try { boq = ($('Parse BoQ Spreadsheet').all() || []).flatMap(i => i.json._boq_items || []); } catch (e) { boq = []; }

const h = src.headers || {};
const g = k => h[k] ?? h[k.toLowerCase()] ?? null;
const list = v => !v ? [] : (Array.isArray(v) ? v : String(v).match(/[\w.+-]+@[\w.-]+\.\w+/g) || []);

// This IMAP server returns some headers with the field name still attached
// ("Delivery-date: Mon, 10 Aug 2026 03:09:44 +0000"). received_date and
// original_sent_date are Datetime on the ticket, so that string never parses
// and the SLA clock silently starts from null. Strip a leading header name --
// letters and hyphens only, so an ISO value like 2026-08-10T03:09:43Z is left
// alone -- then normalise to ISO.
const asDate = v => {
  if (!v) return null;
  const s = String(Array.isArray(v) ? v[0] : v).replace(/^\s*[A-Za-z][A-Za-z-]*:\s*/, '').trim();
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d.toISOString();
};

const items = [...(ext.items || []), ...boq];

return [{ json: {
  message_id:    src.messageId || g('message-id') || '',
  thread_id:     src.threadId || g('references') || '',
  // Sent for the server-side thread check. n8n's Find Thread node runs against a
  // database that does not yet contain tickets created later in the same pass,
  // so ingest repeats the lookup with these headers as the authoritative pass.
  in_reply_to:   src.inReplyTo || g('in-reply-to') || '',
  references:    [].concat(src.references || g('references') || []).join(' '),
  subject:       src._original_subject || src.subject || '',
  // Delivery-date is arrival; the Date header is when the customer sent it. A
  // two-week-old forward would otherwise start life already SLA-breached.
  received_date: asDate(g('delivery-date')) || asDate(src.date) || null,
  sent_date:     asDate(src._original_sent) || asDate(src.date) || null,
  classification: cls.classification || cls.inquiry_type || null,
  confidence:     cls.confidence ?? 0,
  ai_provider:    'Google AI Studio',
  summary:        cls.summary || null,
  priority:       cls.priority || 'Medium',
  headers: {
    envelope_to:  list(g('envelope-to')),
    received_for: src._recipients || [],
    bcc:          list(src.bcc || g('bcc')),
    to:           list(src.to  || g('to')),
    cc:           list(src.cc  || g('cc')),
    from_email:   src._from_email || '',
  },
  contact: {
    first_name:   (ext.contact && ext.contact.first_name) || null,
    last_name:    (ext.contact && ext.contact.last_name) || null,
    name:         src._customer_name || null,
    company_name: (ext.contact && ext.contact.company_name) || null,
    email:        src._customer_email || (ext.contact && ext.contact.email) || null,
    phones:       (ext.contact && ext.contact.phones) || [],
  },
  inquiry: {
    project_name:      ext.project_name || null,
    delivery_location: ext.delivery_location || null,
    due_date:          ext.due_date || null,
    tender_number:     ext.tender_number || null,
  },
  items,
  extracted: ext,
} }];

// The HTTP node returns only the API response and drops binary, so rebuild the
// item from Pre-Filter Noise. Order is 1:1 -- httpRequest emits exactly one
// output item per input item -- so index alignment is safe.
const src = $('Pre-Filter Noise').all();
const res = $input.all();

return src.map((item, i) => {
  let t = {};
  try { t = res[i].json.message || {}; } catch (e) { t = {}; }
  return {
    json: { ...item.json,
      _thread_found:  !!t.found,
      _thread_ticket: t.ticket || null,
      _thread_match:  t.match || null,
      _thread_owner:  t.sales_engineer || null,
      _thread_status: t.status || null,
    },
    binary: item.binary,
  };
});
